CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id UUID PRIMARY KEY, display_name VARCHAR(50) NOT NULL, username VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(16) NOT NULL CHECK(role IN ('STUDENT','TEACHER','ADMIN')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE modules (id VARCHAR(40) PRIMARY KEY, name VARCHAR(100) NOT NULL, emoji VARCHAR(16) NOT NULL, signal VARCHAR(120) NOT NULL, summary TEXT NOT NULL, safety TEXT NOT NULL, sort_order INT NOT NULL);
CREATE TABLE lessons (id VARCHAR(40) PRIMARY KEY, title VARCHAR(160) NOT NULL, emoji VARCHAR(16) NOT NULL, level INT NOT NULL CHECK(level BETWEEN 1 AND 3), duration_minutes INT NOT NULL, topic VARCHAR(120) NOT NULL, description TEXT NOT NULL, module_ids JSONB NOT NULL, goals JSONB NOT NULL, question TEXT NOT NULL, choices JSONB NOT NULL, correct_choice INT NOT NULL, reason TEXT NOT NULL, recipe TEXT NOT NULL, experiment TEXT NOT NULL, takeaway TEXT NOT NULL, default_code TEXT NOT NULL, sort_order INT NOT NULL, published BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE curriculum_projects (id VARCHAR(40) PRIMARY KEY, title VARCHAR(160) NOT NULL, emoji VARCHAR(16) NOT NULL, difficulty VARCHAR(40) NOT NULL, duration_minutes INT NOT NULL, description TEXT NOT NULL, module_ids JSONB NOT NULL, sort_order INT NOT NULL);
CREATE TABLE lesson_progress (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, lesson_id VARCHAR(40) NOT NULL REFERENCES lessons(id), step INT NOT NULL DEFAULT 0 CHECK(step BETWEEN 0 AND 3), prediction TEXT NOT NULL DEFAULT '', observation TEXT NOT NULL DEFAULT '', conclusion TEXT NOT NULL DEFAULT '', completed BOOLEAN NOT NULL DEFAULT FALSE, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id,lesson_id));
CREATE INDEX idx_progress_user_updated ON lesson_progress(user_id,updated_at DESC);
